import java.util.*;
import java.util.stream.*;

public class Report {

    public record Student(String name, String group, List<Integer> grades) {}

    static java.util.Map<String, Double> averageByGroup(java.util.List<Student> students) {
        return students.stream()
                .filter(s -> s.grades() != null && !s.grades().isEmpty())
                .collect(Collectors.groupingBy(
                        Student::group,
                        Collectors.averagingDouble(s -> s.grades().stream()
                                .mapToInt(Integer::intValue)
                                .average()
                                .orElse(0.0))
                ));
    }

    static java.util.List<String> topStudents(java.util.List<Student> students, int n) {
        return students.stream()
                .filter(s -> s.grades() != null && !s.grades().isEmpty())
                .sorted(Comparator.<Student, Double>comparing(s -> s.grades().stream()
                                .mapToInt(Integer::intValue)
                                .average()
                                .orElse(0.0), Comparator.reverseOrder())
                        .thenComparing(Student::name))
                .limit(n)
                .map(Student::name)
                .collect(Collectors.toList());
    }

    static java.util.Optional<Student> best(java.util.List<Student> students, String group) {
        return students.stream()
                .filter(s -> s.group().equals(group))
                .filter(s -> s.grades() != null && !s.grades().isEmpty())
                .max(Comparator.<Student, Double>comparing(s -> s.grades().stream()
                                .mapToInt(Integer::intValue)
                                .average()
                                .orElse(0.0))
                        .thenComparing(Student::name, Comparator.reverseOrder()));
    }
}
