#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <stdexcept>
#include <iomanip>
#include <algorithm>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::string name() const = 0;
    virtual std::unique_ptr<Shape> clone() const = 0;
};

class Circle : public Shape {
    double r_;
public:
    explicit Circle(double r) : r_(r) {
        if (r <= 0) {
            throw std::invalid_argument("Radius must be positive");
        }
    }
    double area() const override {
        return 3.14159265358979 * r_ * r_;
    }
    std::string name() const override {
        return "circle";
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Circle>(r_);
    }
};

class Rect : public Shape {
    double w_, h_;
public:
    Rect(double w, double h) : w_(w), h_(h) {
        if (w <= 0 || h <= 0) {
            throw std::invalid_argument("Width and height must be positive");
        }
    }
    double area() const override {
        return w_ * h_;
    }
    std::string name() const override {
        return "rect";
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Rect>(w_, h_);
    }
};

class Scene {
    std::vector<std::unique_ptr<Shape>> shapes_;
public:
    void add(std::unique_ptr<Shape> s) {
        if (!s) {
            throw std::invalid_argument("Cannot add nullptr shape");
        }
        shapes_.push_back(std::move(s));
    }

    std::size_t size() const {
        return shapes_.size();
    }

    double total_area() const {
        double total = 0.0;
        for (const auto& shape : shapes_) {
            total += shape->area();
        }
        return total;
    }

    std::string largest() const {
        if (shapes_.empty()) {
            throw std::runtime_error("Scene is empty");
        }
        const Shape* largest_shape = shapes_[0].get();
        for (size_t i = 1; i < shapes_.size(); ++i) {
            if (shapes_[i]->area() > largest_shape->area()) {
                largest_shape = shapes_[i].get();
            }
        }
        return largest_shape->name();
    }

    Scene(const Scene& other) {
        for (const auto& shape : other.shapes_) {
            shapes_.push_back(shape->clone());
        }
    }

    Scene& operator=(const Scene& other) {
        if (this != &other) {
            shapes_.clear();
            for (const auto& shape : other.shapes_) {
                shapes_.push_back(shape->clone());
            }
        }
        return *this;
    }

    friend std::ostream& operator<<(std::ostream& os, const Scene& scene) {
        if (scene.shapes_.empty()) {
            return os;
        }

        std::vector<const Shape*> sorted_shapes;
        for (const auto& shape : scene.shapes_) {
            sorted_shapes.push_back(shape.get());
        }

        std::sort(sorted_shapes.begin(), sorted_shapes.end(),
            [](const Shape* a, const Shape* b) {
                return a->area() < b->area();
            });

        os << std::fixed << std::setprecision(2);
        for (size_t i = 0; i < sorted_shapes.size(); ++i) {
            if (i > 0) {
                os << " ";
            }
            os << sorted_shapes[i]->name() << ":" << sorted_shapes[i]->area();
        }
        return os;
    }
};
